@@ -0,0 +1,39 @@
+import { useMutation, useQuery } from "@tanstack/react-query";
+import { useLocale } from "next-intl";
+import { useSession } from "next-auth/react";
+import {
+  getNotifications,
+  markAllNotificationsRead,
+  markNotificationRead,
+} from "@/app/server/actions/notifications";
+import { getQueryClient } from "@/app/utils/queryClient";
+
+/** The caller's in-app feed — polled (no websockets in the base). Disabled entirely when signed out, so the bell doesn't 401-poll for anonymous visitors. */
+export const useNotifications = () => {
+  const locale = useLocale();
+  const { status } = useSession();
+  const isAuthenticated = status === "authenticated";
+  const queryClient = getQueryClient();
+  const queryKey = ["/notifications", "list", locale];
+
+  const query = useQuery({
+    queryKey,
+    queryFn: () => getNotifications({ limit: 20, locale }),
+    enabled: isAuthenticated,
+    refetchInterval: isAuthenticated ? 60_000 : false,
+  });
+
+  const reload = () => queryClient.invalidateQueries({ queryKey: ["/notifications"] });
+
+  const markRead = useMutation({
+    mutationFn: markNotificationRead,
+    onSuccess: reload,
+  });
+
+  const markAllRead = useMutation({
+    mutationFn: markAllNotificationsRead,
+    onSuccess: reload,
+  });
+
+  return { ...query, reload, markRead, markAllRead };
+};
diff --git a/app/hooks/use-push-subscription.ts b/app/hooks/use-push-subscription.ts
new file mode 100644
index 0000000..6e4c8bd
--- /dev/null
+++ b/app/hooks/use-push-subscription.ts
@@ -0,0 +1,87 @@
+"use client";
+
+import { useCallback, useEffect, useState } from "react";
+import {
+  registerPushSubscription,
+  unregisterPushSubscription,
+} from "@/app/server/actions/notifications";
+
+const urlBase64ToUint8Array = (base64: string) => {
+  const padding = "=".repeat((4 - (base64.length % 4)) % 4);
+  const base64Safe = (base64 + padding).replace(/-/g, "+").replace(/_/g, "/");
+  const raw = atob(base64Safe);
+  return Uint8Array.from(raw.split("").map((char) => char.charCodeAt(0)));
+};
+
+/** Web Push permission + subscribe/unsubscribe flow. Must be called from a user gesture; only works in an installed PWA on iOS. */
+export const usePushSubscription = () => {
+  const [supported, setSupported] = useState(false);
+  const [subscribed, setSubscribed] = useState(false);
+  const [loading, setLoading] = useState(false);
+
+  useEffect(() => {
+    const check = async () => {
+      if (!("serviceWorker" in navigator) || !("PushManager" in window)) return;
+      setSupported(true);
+      const registration = await navigator.serviceWorker.ready;
+      const subscription = await registration.pushManager.getSubscription();
+      setSubscribed(!!subscription);
+    };
+    check();
+  }, []);
+
+  const subscribe = useCallback(async () => {
+    const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY;
+    if (!publicKey) return false;
+
+    setLoading(true);
+    try {
+      const permission = await Notification.requestPermission();
+      if (permission !== "granted") return false;
+
+      const registration = await navigator.serviceWorker.ready;
+      const subscription = await registration.pushManager.subscribe({
+        userVisibleOnly: true,
+        applicationServerKey: urlBase64ToUint8Array(publicKey),
+      });
+
+      const ok = await registerPushSubscription(subscription.toJSON());
+      setSubscribed(ok);
+      return ok;
+    } catch (error) {
+      // Permission denial, a malformed VAPID key, or the server call
+      // throwing must not become an unhandled rejection out of the Switch's
+      // onCheckedChange handler — surface as "stayed off" instead.
+      console.error(error);
+      return false;
+    } finally {
+      setLoading(false);
+    }
+  }, []);
+
+  const unsubscribe = useCallback(async () => {
+    setLoading(true);
+    try {
+      const registration = await navigator.serviceWorker.ready;
+      const subscription = await registration.pushManager.getSubscription();
+      if (!subscription) return true;
+
+      await subscription.unsubscribe();
+      // The browser is now unsubscribed regardless of whether the server
+      // call below succeeds — reflect that immediately rather than reading
+      // a stale `subscribed` closure value on server failure.
+      setSubscribed(false);
+
+      const ok = await unregisterPushSubscription(subscription.endpoint);
+      if (!ok) console.error("Failed to unregister push subscription on the server");
+      return ok;
+    } catch (error) {
+      console.error(error);
+      return false;
+    } finally {
+      setLoading(false);
+    }
+  }, []);
+
+  return { supported, subscribed, loading, subscribe, unsubscribe };
+};
