+import { describe, expect, it } from "vitest";
+import { isDue, nextOccurrence } from "@/app/lib/notifications/reminders";
+
+describe("nextOccurrence", () => {
+  it("advances non-daily recurrence not at all (returns scheduledFor unchanged)", () => {
+    const d = new Date("2026-08-03T06:00:00Z");
+    expect(nextOccurrence(d, null, "UTC", d).getTime()).toBe(d.getTime());
+  });
+
+  it("advances exactly 24h in a fixed-offset timezone (no DST) when now is before that", () => {
+    const d = new Date("2026-08-03T06:00:00Z"); // 09:00 in Africa/Cairo (UTC+3, no DST)
+    const next = nextOccurrence(d, "daily", "Africa/Cairo", d);
+    expect(next.getTime() - d.getTime()).toBe(24 * 60 * 60 * 1000);
+  });
+
+  it("preserves local wall-clock time across a US DST fall-back boundary", () => {
+    // 2026-11-01 02:00 local in America/New_York is the fall-back morning (DST ends 2026-11-01 02:00 -> 01:00).
+    // Pick a reminder the day before at 09:00 local and confirm the next occurrence is still 09:00 local.
+    const before = new Date("2026-10-31T13:00:00Z"); // 09:00 EDT (UTC-4)
+    const next = nextOccurrence(before, "daily", "America/New_York", before);
+
+    const formatter = new Intl.DateTimeFormat("en-US", {
+      timeZone: "America/New_York",
+      hourCycle: "h23",
+      hour: "2-digit",
+      minute: "2-digit",
+    });
+    const parts = formatter.formatToParts(next).reduce<Record<string, string>>((acc, p) => {
+      acc[p.type] = p.value;
+      return acc;
+    }, {});
+    expect(`${parts.hour}:${parts.minute}`).toBe("09:00");
+  });
+
+  it("catches up past a multi-day cron outage instead of re-firing in the past", () => {
+    const scheduledFor = new Date("2026-08-01T06:00:00Z");
+    const now = new Date("2026-08-04T10:00:00Z"); // 3+ days later — outage longer than 24h
+    const next = nextOccurrence(scheduledFor, "daily", "UTC", now);
+    expect(next.getTime()).toBeGreaterThan(now.getTime());
+    // Still lands on the original 06:00 UTC time-of-day, just a later day.
+    expect(next.getUTCHours()).toBe(6);
+  });
+
+  it("degrades to UTC instead of throwing on an invalid timezone", () => {
+    const d = new Date("2026-08-03T06:00:00Z");
+    expect(() => nextOccurrence(d, "daily", "Not/ARealZone", d)).not.toThrow();
+  });
+});
+
+describe("isDue", () => {
+  it("is due when scheduledFor is exactly now", () => {
+    const now = new Date("2026-08-03T06:00:00Z");
+    expect(isDue(now, now)).toBe(true);
+  });
+
+  it("is due when scheduledFor is in the past", () => {
+    const now = new Date("2026-08-03T06:00:00Z");
+    const scheduledFor = new Date(now.getTime() - 1000);
+    expect(isDue(scheduledFor, now)).toBe(true);
+  });
+
+  it("is not due when scheduledFor is in the future", () => {
+    const now = new Date("2026-08-03T06:00:00Z");
+    const scheduledFor = new Date(now.getTime() + 1000);
+    expect(isDue(scheduledFor, now)).toBe(false);
+  });
+});
diff --git a/app/lib/notifications/reminders.ts b/app/lib/notifications/reminders.ts
new file mode 100644
index 0000000..97d1e59
--- /dev/null
+++ b/app/lib/notifications/reminders.ts
@@ -0,0 +1,97 @@
+import type { NotificationChannelKey } from "@/app/constants/notifications";
+import type { NotificationStore } from "@/app/lib/notifications/types";
+
+const DAY_MS = 24 * 60 * 60 * 1000;
+
+// A timezone string past this many single-day advances is treated as
+// pathological rather than looped forever — 5 years of daily catch-up.
+const MAX_ADVANCE_STEPS = 365 * 5;
+
+/** `timezone` is client-supplied (see ScheduledNotification.timezone) — an invalid IANA name must degrade to UTC, not throw. */
+const toSafeTimeZone = (timeZone: string): string => {
+  try {
+    new Intl.DateTimeFormat("en-US", { timeZone });
+    return timeZone;
+  } catch {
+    return "UTC";
+  }
+};
+
+const getTimezoneOffsetMs = (date: Date, timeZone: string): number => {
+  const dtf = new Intl.DateTimeFormat("en-US", {
+    timeZone: toSafeTimeZone(timeZone),
+    hourCycle: "h23",
+    year: "numeric",
+    month: "2-digit",
+    day: "2-digit",
+    hour: "2-digit",
+    minute: "2-digit",
+    second: "2-digit",
+  });
+  const parts = dtf.formatToParts(date).reduce<Record<string, string>>((acc, part) => {
+    acc[part.type] = part.value;
+    return acc;
+  }, {});
+  const asUTC = Date.UTC(
+    Number(parts.year),
+    Number(parts.month) - 1,
+    Number(parts.day),
+    Number(parts.hour),
+    Number(parts.minute),
+    Number(parts.second)
+  );
+  return asUTC - date.getTime();
+};
+
+/** One day forward, preserving the same local wall-clock time in `timeZone` (DST-corrected). */
+const advanceOneDay = (from: Date, timeZone: string): Date => {
+  const offsetBefore = getTimezoneOffsetMs(from, timeZone);
+  const naiveNext = new Date(from.getTime() + DAY_MS);
+  const offsetAfter = getTimezoneOffsetMs(naiveNext, timeZone);
+  const dstCorrection = offsetAfter - offsetBefore;
+  return new Date(naiveNext.getTime() - dstCorrection);
+};
+
+/**
+ * Pure: the next `daily`-recurrence instant that preserves the same local
+ * wall-clock time in `timezone`, correcting for DST — and is strictly after
+ * `now`. A single `scheduledFor + 1 day` is not enough: after a cron outage
+ * longer than 24h, that would still land in the past and the reminder would
+ * re-fire on every subsequent poll until it caught up. Non-"daily" recurrence
+ * (including null/one-shot) returns `scheduledFor` unchanged — callers only
+ * advance recurring reminders.
+ */
+export const nextOccurrence = (
+  scheduledFor: Date,
+  recurrence: string | null,
+  timezone: string | null,
+  now: Date
+): Date => {
+  if (recurrence !== "daily") return scheduledFor;
+
+  const tz = timezone ?? "UTC";
+  let next = advanceOneDay(scheduledFor, tz);
+  let steps = 0;
+  while (next.getTime() <= now.getTime() && steps < MAX_ADVANCE_STEPS) {
+    next = advanceOneDay(next, tz);
+    steps++;
+  }
+  return next;
+};
+
+/** Pure: is this reminder due at `now`? */
+export const isDue = (scheduledFor: Date, now: Date): boolean => scheduledFor.getTime() <= now.getTime();
+
+export const scheduleReminder = (
+  store: NotificationStore,
+  input: {
+    userId: number;
+    type: string;
+    payload: unknown;
+    channels?: NotificationChannelKey[];
+    scheduledFor: Date;
+    recurrence?: "daily" | null;
+    timezone?: string | null;
+    dedupeKey?: string;
+  }
+) => store.upsertScheduledReminder(input);
