+import { describe, expect, it } from "vitest";
+import { resolveChannels } from "@/app/lib/notifications/resolve-channels";
+import type { NotificationTypeDef } from "@/app/constants/notifications";
+
+const typeDef: NotificationTypeDef = {
+  key: "test.type",
+  defaultChannels: ["in_app", "push"],
+  render: () => ({ title: "t", body: "b" }),
+};
+
+describe("resolveChannels", () => {
+  it("uses the type's default channels when none are requested", () => {
+    const { selected, skipped } = resolveChannels(typeDef, undefined, ["in_app", "push", "email"]);
+    expect(selected).toEqual(["in_app", "push"]);
+    expect(skipped).toEqual([]);
+  });
+
+  it("an explicit request overrides the type default", () => {
+    const { selected, skipped } = resolveChannels(typeDef, ["email"], ["in_app", "push", "email"]);
+    expect(selected).toEqual(["email"]);
+    expect(skipped).toEqual([]);
+  });
+
+  it("a channel not in `available` is recorded as skipped, not dropped", () => {
+    const { selected, skipped } = resolveChannels(typeDef, undefined, ["in_app"]);
+    expect(selected).toEqual(["in_app"]);
+    expect(skipped).toEqual(["push"]);
+  });
+
+  it("an empty requested array falls back to defaults rather than selecting nothing", () => {
+    const { selected } = resolveChannels(typeDef, [], ["in_app", "push", "email"]);
+    expect(selected).toEqual(["in_app", "push"]);
+  });
+});
diff --git a/app/lib/notifications/resolve-channels.ts b/app/lib/notifications/resolve-channels.ts
new file mode 100644
index 0000000..c6bca29
--- /dev/null
+++ b/app/lib/notifications/resolve-channels.ts
@@ -0,0 +1,34 @@
+import type { NotificationChannelKey, NotificationTypeDef } from "@/app/constants/notifications";
+
+export type ResolveChannelsResult = {
+  selected: NotificationChannelKey[];
+  /** Channels chosen (explicitly or by default) but not in `available` — recorded as `skipped` deliveries, never silently dropped. */
+  skipped: NotificationChannelKey[];
+};
+
+/**
+ * Pure channel-selection logic — the seam for user preferences later (a
+ * prefs lookup becomes one more input here; dispatch.ts never changes).
+ * Precedence: explicit `requested` wins over the type's `defaultChannels`.
+ */
+export const resolveChannels = (
+  typeDef: NotificationTypeDef,
+  requested: NotificationChannelKey[] | undefined,
+  available: NotificationChannelKey[]
+): ResolveChannelsResult => {
+  const wanted = requested && requested.length > 0 ? requested : typeDef.defaultChannels;
+  const availableSet = new Set(available);
+
+  const selected: NotificationChannelKey[] = [];
+  const skipped: NotificationChannelKey[] = [];
+
+  for (const channel of wanted) {
+    if (availableSet.has(channel)) {
+      selected.push(channel);
+    } else {
+      skipped.push(channel);
+    }
+  }
+
+  return { selected, skipped };
+};
diff --git a/app/lib/notifications/types.ts b/app/lib/notifications/types.ts
new file mode 100644
